254	// captureClaudeTuiQuotaViaPTY drives the /usage probe through ptyquota.Run
255	// and returns parsed windows and account info. This is the shared probe
256	// machinery that both claude and claude-tui use.
257	func captureClaudeTuiQuotaViaPTY(ctx context.Context, timeout time.Duration) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, ptyquota.Result, error) {
258		var windows []harnesses.QuotaWindow
259		var account *harnesses.AccountInfo
260	
261		result, err := ptyquota.Run(ctx, ptyquota.Config{
262			HarnessName:  "claude-tui",
263			Binary:       "claude",
264			Args:         nil,
265			Workdir:      "",
266			Env:          nil,
267			Command:      "/usage\r",
268			ReadyMarkers: []string{"❯", "> "},
269			DoneWhen:     claudettuiUsageComplete,
270			Timeout:      timeout,
271			Size:         session.Size{Rows: 50, Cols: 220},
272			Quota: func(text string) (cassette.QuotaRecord, error) {
273				windows, account = parseClaudeTuiUsageOutput(text)
274				if len(windows) == 0 {
275					return cassette.QuotaRecord{}, fmt.Errorf("no quota windows found in claude /usage output")
276				}
277				if err := validateClaudeTuiQuotaEvidence(windows, account); err != nil {
278					return cassette.QuotaRecord{}, fmt.Errorf("incomplete claude /usage output: %w", err)
279				}
280				return quotaRecord(windows, map[string]any{"plan_type": accountPlan(account)}), nil
281			},
282		})
283		if err != nil {
284			return nil, nil, result, err
285		}
286		if len(windows) == 0 {
287			windows, account = parseClaudeTuiUsageOutput(result.Text)
288		}
289		if len(windows) == 0 {
290			return nil, account, result, fmt.Errorf("no quota windows found in claude /usage output")
291		}
292		if err := validateClaudeTuiQuotaEvidence(windows, account); err != nil {
293			return nil, account, result, fmt.Errorf("incomplete claude /usage output: %w", err)
294		}
295		return windows, account, result, nil
296	}
297	
298	// Helper functions for parsing and validation
299	
300	func claudettuiQuotaSnapshotFromWindows(windows []harnesses.QuotaWindow, account *harnesses.AccountInfo) anthropic.ClaudeQuotaSnapshot {
301		fiveHourUsed := usedPercentFor(windows, "session")
302		weeklyUsed := usedPercentFor(windows, "weekly-all")
303		if weeklyUsed < 0 {
304			weeklyUsed = usedPercentFor(windows, "weekly-sonnet")
305		}
306		return anthropic.ClaudeQuotaSnapshot{
307			CapturedAt:        time.Now().UTC(),
308			FiveHourLimit:     100,
309			FiveHourRemaining: remainingPercent(fiveHourUsed),
310			WeeklyLimit:       100,
311			WeeklyRemaining:   remainingPercent(weeklyUsed),
312			Windows:           append([]harnesses.QuotaWindow(nil), windows...),
313			Source:            "pty",
314			Account:           account,
315		}
316	}
317	
318	func usedPercentFor(windows []harnesses.QuotaWindow, limitID string) float64 {
319		for _, window := range windows {
320			if window.LimitID == limitID {
321				return window.UsedPercent
322			}
323		}
324		return -1
325	}
326	
327	func hasQuotaWindow(windows []harnesses.QuotaWindow, limitID string) bool {
328		return usedPercentFor(windows, limitID) >= 0
329	}
330	
331	func claudettuiUsageComplete(text string) bool {
332		windows, _ := parseClaudeTuiUsageOutput(text)
333		return hasQuotaWindow(windows, "session") && (hasQuotaWindow(windows, "weekly-all") || hasQuotaWindow(windows, "weekly-sonnet"))
334	}
335	
336	func validateClaudeTuiQuotaEvidence(windows []harnesses.QuotaWindow, account *harnesses.AccountInfo) error {
337		if accountPlan(account) == "" {
338			return fmt.Errorf("missing account plan")
339		}
340		if !hasQuotaWindow(windows, "session") {
341			return fmt.Errorf("missing session window")
342		}
343		if !hasQuotaWindow(windows, "weekly-all") && !hasQuotaWindow(windows, "weekly-sonnet") {
344			return fmt.Errorf("missing weekly window")
345		}
346		return nil
347	}
348	
349	func remainingPercent(used float64) int {
350		if used < 0 {
351			return 0
352		}
353		remaining := int(100 - used)
354		if remaining < 0 {
355			return 0
356		}
357		if remaining > 100 {
358			return 100
359		}
360		return remaining
361	}
362	
363	func quotaRecord(windows []harnesses.QuotaWindow, metadata map[string]any) cassette.QuotaRecord {
364		records := make([]map[string]any, 0, len(windows))
365		for _, window := range windows {
366			records = append(records, map[string]any{
367				"name":           window.Name,
368				"limit_id":       window.LimitID,
369				"window_minutes": window.WindowMinutes,
370				"used_percent":   window.UsedPercent,
371				"resets_at":      window.ResetsAt,
372				"state":          window.State,
373			})
374		}
375		accountClass, _ := metadata["plan_type"].(string)
376		return cassette.QuotaRecord{
377			Source:            "pty",
378			Status:            string(ptyquota.StatusOK),
379			CapturedAt:        time.Now().UTC().Format(time.RFC3339),
380			FreshnessWindow:   claudettuiQuotaFreshness.String(),
381			StalenessBehavior: "stale quota evidence keeps Claude out of automatic routing and is treated as limited",
382			AccountClass:      accountClass,
383			Windows:           records,
384			Metadata:          metadata,
385		}
386	}
387	
388	func accountPlan(account *harnesses.AccountInfo) string {
389		if account == nil {
390			return ""
391		}
392		return account.PlanType
393	}
394	
395	// parseClaudeTuiUsageOutput delegates to the shared parsing from the anthropic package.
396	// Both claude and claude-tui use the same /usage output format, so they share the same parser.
397	func parseClaudeTuiUsageOutput(text string) ([]harnesses.QuotaWindow, *harnesses.AccountInfo) {
398		return anthropic.ParseClaudeUsageOutput(text)
399	}
