35	// Harness is the sentinel harness for claude TUI.
36	// It satisfies the harnesses.Harness, harnesses.QuotaHarness,
37	// harnesses.AccountHarness, and harnesses.ModelDiscoveryHarness interfaces
38	// via stub implementations that return ErrNotYetImplemented.
39	type Harness struct {
40	}
41	
42	// Info implements harnesses.Harness.
43	func (h *Harness) Info() harnesses.HarnessInfo {
44		return harnesses.HarnessInfo{
45			Name:                "claude-tui",
46			Type:                "subprocess",
47			Available:           false,
48			IsSubscription:      true,
49			AutoRoutingEligible: false,
50			DefaultModel:        "claude-sonnet-4-6",
51		}
52	}
