305	// composeSettingsJSON builds the --settings JSON with hook definitions.
306	// Returns the JSON string and any warnings from hook conflicts.
307	func composeSettingsJSON(hookPayloads map[string]string, logger *slog.Logger) (string, []string) {
308		var warnings []string
309	
310		// Build the hooks settings
311		hooks := make(map[string]interface{})
312		for hookName, command := range hookPayloads {
313			hooks[hookName] = map[string]interface{}{
314				"command": command,
315				"shell":   "sh",
316			}
317		}
318	
319		settings := map[string]interface{}{
320			"hooks": hooks,
321		}
322	
323		// Check for conflicts with existing user settings
324		homeDir, err := os.UserHomeDir()
325		if err == nil {
326			userSettingsPath := filepath.Join(homeDir, ".claude", "settings.json")
327			if fileExists(userSettingsPath) {
328				// Read user settings and check for conflicting hooks
329				userData, err := ioutil.ReadFile(userSettingsPath)
330				if err == nil {
331					var userSettings map[string]interface{}
332					if err := json.Unmarshal(userData, &userSettings); err == nil {
333						if userHooks, ok := userSettings["hooks"].(map[string]interface{}); ok {
334							for hookName := range userHooks {
335								if _, conflict := hooks[hookName].(map[string]interface{}); conflict {
336									msg := fmt.Sprintf("hook conflict: %s already defined in ~/.claude/settings.json (will be overridden)", hookName)
337									warnings = append(warnings, msg)
338									logger.Warn("hook conflict detected", "hook", hookName)
339								}
340							}
341						}
342					}
343				}
344			}
345		}
346	
347		// Marshal to JSON
348		jsonBytes, _ := json.Marshal(settings)
349		return string(jsonBytes), warnings
350	}
