352	// readStopHookPayload reads the transcript path from the stop hook payload file.
353	func readStopHookPayload(payloadPath string) (string, error) {
354		// Wait briefly for hook to write the file
355		maxAttempts := 20
356		for i := 0; i < maxAttempts; i++ {
357			data, err := ioutil.ReadFile(payloadPath)
358			if err == nil {
359				return ReadHookPayload(data)
360			}
361			if i < maxAttempts-1 {
362				time.Sleep(50 * time.Millisecond)
363			}
364		}
365		return "", fmt.Errorf("stop hook payload not written within timeout")
366	}
