452	// readClaudeTuiModelDiscoveryViaPTY spawns a PTY session against the claude CLI,
453	// sends the /model command, and parses the output to extract available models.
454	// Per the no-static-fallback principle, returns ErrModelDiscoveryEvidenceMissing
455	// if the PTY fails or yields no models; never returns a partial or empty snapshot.
456	func readClaudeTuiModelDiscoveryViaPTY(ctx context.Context, timeout time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
457		// Variable to capture the snapshot once discovery succeeds.
458		var snapshot harnesses.ModelDiscoverySnapshot
459		var discoveryErr error
460	
461		_, err := ptyquota.Run(ctx, ptyquota.Config{
462			HarnessName:  "claude-tui",
463			Binary:       "claude",
464			Args:         nil,
465			Workdir:      "",
466			Env:          nil,
467			Command:      "/model\r",
468			ReadyMarkers: []string{"❯", "> "},
469			DoneWhen:     claudeTuiModelDiscoveryComplete,
470			Timeout:      timeout,
471			Size:         session.Size{Rows: 50, Cols: 220},
472			Discovery: func(text string) (cassette.DiscoveryRecord, error) {
473				models := ParseClaudeTuiModels(text)
474				if len(models) == 0 {
475					discoveryErr = harnesses.ErrModelDiscoveryEvidenceMissing
476					return cassette.DiscoveryRecord{}, fmt.Errorf("no models found in /model output")
477				}
478				// Build snapshot only after confirming we have models.
479				snapshot.CapturedAt = time.Now().UTC()
480				snapshot.FreshnessWindow = (24 * time.Hour).String()
481				snapshot.Source = "pty"
482				snapshot.Models = models
483				snapshot.ReasoningLevels = ParseClaudeTuiReasoningLevels(text)
484				return discoveryRecordFromSnapshot(snapshot), nil
485			},
486		})
487		if err != nil {
488			if discoveryErr != nil {
489				return emptyModelSnapshot, discoveryErr
490			}
491			return emptyModelSnapshot, fmt.Errorf("model discovery PTY: %w", err)
492		}
493		if len(snapshot.Models) == 0 {
494			return emptyModelSnapshot, harnesses.ErrModelDiscoveryEvidenceMissing
495		}
496		return snapshot, nil
497	}
