562	func uniqueMatches(values []string) []string {
563		out := make([]string, 0, len(values))
564		for _, value := range values {
565			out = appendUniqueString(out, value)
566		}
567		return out
568	}
569	
570	func appendUniqueString(values []string, value string) []string {
571		value = strings.TrimSpace(value)
572		if value == "" {
573			return values
574		}
575		for _, existing := range values {
576			if existing == value {
577				return values
578			}
579		}
580		return append(values, value)
581	}
