1	// Package discoverycache implements the per-source on-disk cache described in
2	// ADR-012. It provides a two-tier lock + long-lived refresh marker pattern so
3	// that slow discovery IO (PTY ~30 s, HTTP ~316 ms) never blocks UI reads.
4	//
5	// Public surface: Cache.Read, Cache.Refresh, Cache.MaybeRefresh, Cache.Prune.
6	// The Refresher function is injected; the cache manages single-flight
7	// deduplication, atomic writes, and crash recovery.
8	package discoverycache
9	
10	import (
11		"context"
12		"errors"
13		"io/fs"
14		"os"
15		"path/filepath"
16		"strings"
17		"time"
18	
19		"golang.org/x/sync/singleflight"
20	)
21	
22	const (
23		lockAcquisitionTimeout = 100 * time.Millisecond
24		lockPollInterval       = 5 * time.Millisecond
25		waitPollInterval       = 250 * time.Millisecond
26		stalenessMultiplier    = time.Duration(2)
27		refreshFailureCooldown = 250 * time.Millisecond
28	)
29	
30	// Cache is the root handle. Root is the base directory (e.g. ~/.cache/fizeau).
31	// Each Cache instance owns one in-process singleflight.Group; a new Cache per
32	// process is the normal usage.
33	type Cache struct {
34		Root string
35		sf   singleflight.Group
36	
37		waitForRefreshHook func(Source)
38	}
39	
40	// Source describes one cacheable data stream (one file under Root/Tier/Name.json).
41	type Source struct {
42		// Tier is "discovery" or "runtime".
43		Tier string
44		// Name is the kebab-case source identifier (e.g. "openrouter").
45		Name string
46		// TTL controls freshness: Read returns Fresh=true when Age < TTL.
47		TTL time.Duration
48		// RefreshDeadline is the maximum time a refresh is expected to take.
49		// Also controls the staleness threshold: 2 × RefreshDeadline.
50		RefreshDeadline time.Duration
51	}
52	
53	func (s Source) key() string { return s.Tier + "/" + s.Name }
54	
55	// ReadResult is the output of Cache.Read.
56	type ReadResult struct {
57		// Data is the raw bytes from the cache file; nil if no file exists.
58		Data []byte
59		// Age is how long ago the data was written (0 if absent).
60		Age time.Duration
61		// Fresh is true when Age < TTL and Data is non-nil.
62		Fresh bool
63		// Stale is true when Data is nil or Age >= TTL.
64		Stale bool
65	}
66	
67	// RefreshState reports the current marker state for a source. It is used by
68	// higher layers to surface refresh_failed / in-flight diagnostics without
69	// re-reading raw marker files.
70	type RefreshState struct {
71		InFlight  bool
72		Failed    bool
73		LastError string
74		StartedAt time.Time
75		Deadline  time.Time
76	}
77	
78	// Refresher is the source-fetch function injected by the caller. The cache
79	// handles single-flight deduplication, the atomic write, and marker lifecycle.
80	type Refresher func(ctx context.Context) ([]byte, error)
81	
82	// Read returns cached data without any IO beyond reading the local file.
83	// It never blocks on network or PTY. If no cache file exists, Data is nil and
84	// Stale is true. Stale data is always returned without error; the caller
85	// decides whether to trigger a background refresh.
86	func (c *Cache) Read(s Source) (ReadResult, error) {
87		path := c.dataPath(s)
88		data, err := os.ReadFile(path) // #nosec G304
89		if errors.Is(err, os.ErrNotExist) {
90			return ReadResult{Stale: true}, nil
91		}
92		if err != nil {
93			return ReadResult{}, err
94		}
95		info, err := os.Stat(path)
96		if err != nil {
97			// File was just there; best-effort fallback.
98			return ReadResult{Data: data, Stale: true}, nil
99		}
100		age := time.Since(info.ModTime())
101		if age < 0 {
102			age = 0
103		}
104		fresh := age < s.TTL
105		return ReadResult{
106			Data:  data,
107			Age:   age,
108			Fresh: fresh,
109			Stale: !fresh,
110		}, nil
111	}
