113	// Prune removes data files (and their sidecar lock/marker/tmp files) for
114	// sources not listed in activeSources. Sources with an active .refreshing
115	// marker are skipped. Prune acquires the tier-1 lock before removing each
116	// source's files.
117	func (c *Cache) Prune(activeSources []Source) error {
118		active := make(map[string]bool, len(activeSources))
119		for _, s := range activeSources {
120			active[s.key()] = true
121		}
122	
123		return filepath.WalkDir(c.Root, func(path string, d fs.DirEntry, err error) error {
124			if err != nil || d.IsDir() {
125				return nil
126			}
127			if !strings.HasSuffix(d.Name(), ".json") {
128				return nil
129			}
130			rel, rerr := filepath.Rel(c.Root, path)
131			if rerr != nil {
132				return nil
133			}
134			parts := strings.SplitN(rel, string(filepath.Separator), 2)
135			if len(parts) != 2 {
136				return nil
137			}
138			tier := parts[0]
139			name := strings.TrimSuffix(parts[1], ".json")
140			if strings.ContainsRune(name, filepath.Separator) {
141				return nil // nested dir, skip
142			}
143	
144			if active[tier+"/"+name] {
145				return nil
146			}
147	
148			s := Source{Tier: tier, Name: name}
149	
150			// Skip sources with an active refresh in progress.
151			m, _ := readMarker(c.markerPath(s))
152			if isMarkerActiveForPrune(m) {
153				return nil
154			}
155	
156			release, lerr := c.acquireLock(s)
157			if lerr != nil {
158				return nil // can't lock; skip this source
159			}
160			defer release()
161	
162			// Re-check under lock.
163			m2, _ := readMarker(c.markerPath(s))
164			if isMarkerActiveForPrune(m2) {
165				return nil
166			}
167	
168			_ = os.Remove(c.dataPath(s))
169			_ = os.Remove(c.markerPath(s))
170			_ = os.Remove(c.tmpPath(s))
171			return nil
172		})
173	}
174	
175	// RefreshState reports the current refresh marker status for s.
176	func (c *Cache) RefreshState(s Source) (RefreshState, error) {
177		m, err := readMarker(c.markerPath(s))
178		if err != nil || m == nil {
179			return RefreshState{}, err
180		}
181		return RefreshState{
182			InFlight:  !isStale(s, m),
183			Failed:    strings.TrimSpace(m.LastError) != "",
184			LastError: strings.TrimSpace(m.LastError),
185			StartedAt: m.StartedAt,
186			Deadline:  m.Deadline,
187		}, nil
188	}
