198	type claimResult struct {
199		claimed bool
200		marker  *refreshMarker
201	}
202	
203	// claimRefresh implements Algorithm 1 from ADR-012. Must be called with the
204	// source directory already created (ensured by refreshAndCommit).
205	func (c *Cache) claimRefresh(s Source) (claimResult, error) {
206		release, err := c.acquireLock(s)
207		if err != nil {
208			return claimResult{}, err
209		}
210		defer release()
211	
212		existing, _ := readMarker(c.markerPath(s))
213		if existing != nil {
214			if isStale(s, existing) {
215				_ = os.Remove(c.markerPath(s))
216			} else {
217				return claimResult{claimed: false, marker: existing}, nil
218			}
219		}
220	
221		m := &refreshMarker{
222			PID:       os.Getpid(),
223			StartedAt: time.Now().UTC(),
224			Deadline:  time.Now().UTC().Add(s.RefreshDeadline),
225		}
226		if werr := writeMarker(c.markerPath(s), m); werr != nil {
227			return claimResult{}, werr
228		}
229		return claimResult{claimed: true}, nil
230	}
231	
232	// refreshAndCommit implements Algorithm 2 from ADR-012.
233	func (c *Cache) refreshAndCommit(s Source, fn Refresher) error {
234		if err := os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750); err != nil {
235			return err
236		}
237	
238		claim, err := c.claimRefresh(s)
239		if err != nil {
240			return err
241		}
242		if !claim.claimed {
243			if c.waitForRefreshHook != nil {
244				c.waitForRefreshHook(s)
245			}
246			// Another process is refreshing; wait for it.
247			return c.waitForRefresh(s, claim.marker)
248		}
249	
250		return c.refreshWithClaim(s, fn)
251	}
252	
253	// refreshWithClaim assumes the current process already owns the refresh
254	// marker.
255	func (c *Cache) refreshWithClaim(s Source, fn Refresher) error {
256		// Run slow IO outside any lock.
257		refreshCtx := context.Background()
258		var cancel context.CancelFunc
259		if s.RefreshDeadline > 0 {
260			refreshCtx, cancel = context.WithTimeout(refreshCtx, s.RefreshDeadline)
261		}
262		if cancel != nil {
263			defer cancel()
264		}
265		data, fetchErr := fn(refreshCtx)
266		if fetchErr != nil {
267			c.recordRefreshFailure(s, fetchErr)
268			return fetchErr
269		}
270	
271		if werr := atomicWrite(c.dataPath(s), data); werr != nil {
272			c.recordRefreshFailure(s, werr)
273			return werr
274		}
275	
276		c.releaseMarker(s)
277		return nil
278	}
279	
280	// recordRefreshFailure keeps the marker in place with the failure details so
281	// callers observe refresh_failed state and do not immediately re-probe.
282	func (c *Cache) recordRefreshFailure(s Source, refreshErr error) {
283		release, err := c.acquireLock(s)
284		if err != nil {
285			return
286		}
287		defer release()
288	
289		m, _ := readMarker(c.markerPath(s))
290		if m == nil || m.PID != os.Getpid() {
291			return
292		}
293		now := time.Now().UTC()
294		m.StartedAt = now
295		m.Deadline = now.Add(refreshFailureCooldown)
296		m.LastError = refreshErr.Error()
297		_ = writeMarker(c.markerPath(s), m)
298	}
299	
300	// waitForRefresh implements Algorithm 3 from ADR-012. Polls until the marker
301	// disappears or becomes stale, then returns (data has been written).
302	func (c *Cache) waitForRefresh(s Source, m *refreshMarker) error {
303		// Poll until deadline + staleness_threshold or s.RefreshDeadline, whichever first.
304		threshold := s.RefreshDeadline * stalenessMultiplier
305		absoluteDeadline := m.Deadline.Add(threshold)
306		maxWait := time.Now().Add(s.RefreshDeadline)
307		if maxWait.Before(absoluteDeadline) {
308			absoluteDeadline = maxWait
309		}
310	
311		for time.Now().Before(absoluteDeadline) {
312			time.Sleep(waitPollInterval)
313			current, _ := readMarker(c.markerPath(s))
314			if current == nil || isStale(s, current) {
315				return nil
316			}
317		}
318		return nil // timed out; caller will read whatever is on disk
319	}
320	
321	// releaseMarker removes the .refreshing marker under the tier-1 lock, but
322	// only if our PID is still recorded (guard against PID-reuse races, per §2
323	// of refreshAndCommit pseudocode in ADR-012).
324	func (c *Cache) releaseMarker(s Source) {
325		release, err := c.acquireLock(s)
326		if err != nil {
327			return
328		}
329		defer release()
330		m, _ := readMarker(c.markerPath(s))
331		if m != nil && m.PID == os.Getpid() {
332			_ = os.Remove(c.markerPath(s))
333		}
334	}
