package claudetui

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/pty/cassette"
)

// ---- test seams -------------------------------------------------------------

// setModelDiscoveryProbeForTest swaps the package-level live PTY probe so
// tests can inject deterministic responses without spawning the claude
// binary. The previous probe is restored on test cleanup.
func setModelDiscoveryProbeForTest(t *testing.T, fn func(ctx context.Context, timeout time.Duration) (harnesses.ModelDiscoverySnapshot, error)) {
	t.Helper()
	prev := modelDiscoveryProbe
	modelDiscoveryProbe = fn
	t.Cleanup(func() { modelDiscoveryProbe = prev })
}

// setModelDiscoveryTimeoutForTest shortens the configurable live-probe
// timeout (also the discoverycache RefreshDeadline) for the duration of a
// test.
func setModelDiscoveryTimeoutForTest(t *testing.T, d time.Duration) {
	t.Helper()
	prev := modelDiscoveryTimeout
	modelDiscoveryTimeout = d
	t.Cleanup(func() { modelDiscoveryTimeout = prev })
}

// setModelDiscoveryCacheRootForTest points the shared discovery cache at an
// isolated root and resets the singleton so a stale on-disk snapshot from a
// real run cannot bleed into the test.
func setModelDiscoveryCacheRootForTest(t *testing.T, root string) {
	t.Helper()
	modelDiscoveryCacheMu.Lock()
	prevRoot := modelDiscoveryCacheRoot
	prevInstance := modelDiscoveryCacheInstance
	modelDiscoveryCacheRoot = root
	modelDiscoveryCacheInstance = nil
	modelDiscoveryCacheMu.Unlock()
	t.Cleanup(func() {
		modelDiscoveryCacheMu.Lock()
		modelDiscoveryCacheRoot = prevRoot
		modelDiscoveryCacheInstance = prevInstance
		modelDiscoveryCacheMu.Unlock()
	})
}

// testModelSnapshot is a deterministic snapshot returned by injected probes.
// Composite literals of harnesses.ModelDiscoverySnapshot are permitted in
// test files; the no-static-fallback AST scan only covers production code.
func testModelSnapshot() harnesses.ModelDiscoverySnapshot {
	return harnesses.ModelDiscoverySnapshot{
		CapturedAt:      time.Now().UTC(),
		Models:          []string{"claude-sonnet-4-6", "sonnet", "claude-opus-4-7", "opus", "claude-haiku-5-5", "haiku"},
		ReasoningLevels: []string{"low", "medium", "high"},
		Source:          "pty",
		FreshnessWindow: modelDiscoveryTTL.String(),
	}
}

// ---- AC2: timeout -----------------------------------------------------------

// TestClaudeTuiDefaultModelSnapshotTimeout asserts AC2: a hanging synthetic
// PTY makes DefaultModelSnapshot return ErrModelDiscoveryEvidenceMissing with
// a wrapped context.DeadlineExceeded once the configurable timeout elapses.
func TestClaudeTuiDefaultModelSnapshotTimeout(t *testing.T) {
	setModelDiscoveryCacheRootForTest(t, t.TempDir())
	setModelDiscoveryTimeoutForTest(t, 50*time.Millisecond)
	setModelDiscoveryProbeForTest(t, func(ctx context.Context, _ time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
		// Hang until the refresh context's deadline fires.
		<-ctx.Done()
		return emptyModelSnapshot, ctx.Err()
	})

	start := time.Now()
	_, err := (&Harness{}).DefaultModelSnapshot()
	elapsed := time.Since(start)

	if !errorsIs(err, harnesses.ErrModelDiscoveryEvidenceMissing) {
		t.Fatalf("err = %v, want wrapped ErrModelDiscoveryEvidenceMissing", err)
	}
	if !errorsIs(err, context.DeadlineExceeded) {
		t.Fatalf("err = %v, want wrapped context.DeadlineExceeded", err)
	}
	if elapsed > 5*time.Second {
		t.Fatalf("DefaultModelSnapshot took %s; timeout did not bound the probe", elapsed)
	}
}

// ---- AC3: single-flight -----------------------------------------------------

// TestClaudeTuiDefaultModelSnapshotSingleFlight asserts AC3: concurrent
// DefaultModelSnapshot calls coalesce to a single PTY probe via the
// discoverycache single-flight layer.
func TestClaudeTuiDefaultModelSnapshotSingleFlight(t *testing.T) {
	setModelDiscoveryCacheRootForTest(t, t.TempDir())

	var probeCount int64
	probeStarted := make(chan struct{})
	release := make(chan struct{})
	var once sync.Once
	setModelDiscoveryProbeForTest(t, func(ctx context.Context, _ time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
		atomic.AddInt64(&probeCount, 1)
		once.Do(func() { close(probeStarted) })
		// Hold the probe open until all goroutines are in flight so the
		// single-flight window is unambiguous.
		select {
		case <-release:
		case <-ctx.Done():
		}
		return testModelSnapshot(), nil
	})

	const n = 16
	var wg sync.WaitGroup
	errs := make([]error, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			_, errs[idx] = (&Harness{}).DefaultModelSnapshot()
		}(i)
	}

	// Once the first probe is running, give the rest a moment to pile onto
	// the same single-flight cohort, then release.
	<-probeStarted
	time.Sleep(50 * time.Millisecond)
	close(release)
	wg.Wait()

	for i, err := range errs {
		if err != nil {
			t.Errorf("goroutine %d: DefaultModelSnapshot error = %v", i, err)
		}
	}
	if got := atomic.LoadInt64(&probeCount); got != 1 {
		t.Fatalf("probe invocations = %d, want 1 (single-flight coalescing)", got)
	}
}

// ---- AC4: stale-cache refresh -----------------------------------------------

// TestClaudeTuiDefaultModelSnapshotStaleRefresh asserts AC4: a fresh cache
// entry is served without a probe, and after the TTL elapses the next
// snapshot triggers a fresh live probe.
func TestClaudeTuiDefaultModelSnapshotStaleRefresh(t *testing.T) {
	setModelDiscoveryCacheRootForTest(t, t.TempDir())

	var probeCount int64
	setModelDiscoveryProbeForTest(t, func(ctx context.Context, _ time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
		atomic.AddInt64(&probeCount, 1)
		return testModelSnapshot(), nil
	})

	h := &Harness{}

	// Cold cache: one probe, result cached.
	if _, err := h.DefaultModelSnapshot(); err != nil {
		t.Fatalf("first snapshot: %v", err)
	}
	if got := atomic.LoadInt64(&probeCount); got != 1 {
		t.Fatalf("after first call probes = %d, want 1", got)
	}

	// Within TTL: cache hit, no fresh probe.
	if _, err := h.DefaultModelSnapshot(); err != nil {
		t.Fatalf("second snapshot: %v", err)
	}
	if got := atomic.LoadInt64(&probeCount); got != 1 {
		t.Fatalf("within-TTL call probes = %d, want 1 (cache hit)", got)
	}

	// Fast-forward the clock past the TTL by aging the cache file.
	old := time.Now().Add(-2 * modelDiscoveryTTL)
	if err := os.Chtimes(modelDiscoveryDataPath(), old, old); err != nil {
		t.Fatalf("age cache file: %v", err)
	}

	// Stale cache: a fresh live probe runs.
	if _, err := h.DefaultModelSnapshot(); err != nil {
		t.Fatalf("post-TTL snapshot: %v", err)
	}
	if got := atomic.LoadInt64(&probeCount); got != 2 {
		t.Fatalf("post-TTL call probes = %d, want 2 (stale refresh)", got)
	}
}

// ---- AC1: cached success path ----------------------------------------------

// TestClaudeTuiDefaultModelSnapshotCachesResult asserts AC1: a successful
// probe is persisted through the cache so a follow-up call returns the same
// snapshot from disk without re-probing.
func TestClaudeTuiDefaultModelSnapshotCachesResult(t *testing.T) {
	setModelDiscoveryCacheRootForTest(t, t.TempDir())

	var probeCount int64
	setModelDiscoveryProbeForTest(t, func(ctx context.Context, _ time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
		atomic.AddInt64(&probeCount, 1)
		return testModelSnapshot(), nil
	})

	h := &Harness{}
	snap, err := h.DefaultModelSnapshot()
	if err != nil {
		t.Fatalf("snapshot: %v", err)
	}
	if len(snap.Models) == 0 {
		t.Fatal("snapshot has no models")
	}

	// The cache file exists on disk per ADR-012.
	if _, statErr := os.Stat(modelDiscoveryDataPath()); statErr != nil {
		t.Fatalf("cache file not written: %v", statErr)
	}

	if _, err := h.DefaultModelSnapshot(); err != nil {
		t.Fatalf("cached snapshot: %v", err)
	}
	if got := atomic.LoadInt64(&probeCount); got != 1 {
		t.Fatalf("probe invocations = %d, want 1 (result cached)", got)
	}
}

// TestClaudeTuiDefaultModelSnapshotProbeFailure asserts AC1's failure path:
// a probe error on a cold cache surfaces ErrModelDiscoveryEvidenceMissing.
func TestClaudeTuiDefaultModelSnapshotProbeFailure(t *testing.T) {
	setModelDiscoveryCacheRootForTest(t, t.TempDir())
	setModelDiscoveryProbeForTest(t, func(ctx context.Context, _ time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
		return emptyModelSnapshot, context.Canceled
	})

	_, err := (&Harness{}).DefaultModelSnapshot()
	if !errorsIs(err, harnesses.ErrModelDiscoveryEvidenceMissing) {
		t.Fatalf("err = %v, want wrapped ErrModelDiscoveryEvidenceMissing", err)
	}
}

// ---- AC7: cassette replay ---------------------------------------------------

// TestClaudeTuiModelSurfaceCassetteReplay asserts AC7: the recorded
// model_surface cassette is a valid ADR-002 fixture and the claude-tui
// parser yields a non-empty snapshot covering the canonical families.
func TestClaudeTuiModelSurfaceCassetteReplay(t *testing.T) {
	dir := filepath.Join("testdata", "model_surface")

	reader, err := cassette.Open(dir)
	if err != nil {
		t.Fatalf("open cassette: %v", err)
	}
	if name := reader.Manifest().Harness.Name; name != "claude-tui" {
		t.Fatalf("cassette harness name = %q, want claude-tui", name)
	}

	// Replay-only: parse the recorded surface and assert a non-empty snapshot.
	text := reader.Final().FinalText
	if text == "" {
		frames := reader.Frames()
		if len(frames) > 0 {
			text = strings.Join(frames[len(frames)-1].Text, "\n")
		}
	}
	models := ParseClaudeTuiModels(text)
	if len(models) == 0 {
		t.Fatalf("ParseClaudeTuiModels yielded no models from cassette text %q", text)
	}

	hasSonnet, hasOpus, hasHaiku := false, false, false
	for _, m := range models {
		switch {
		case strings.Contains(m, "sonnet"):
			hasSonnet = true
		case strings.Contains(m, "opus"):
			hasOpus = true
		case strings.Contains(m, "haiku"):
			hasHaiku = true
		}
	}
	if !hasSonnet || !hasOpus || !hasHaiku {
		t.Fatalf("cassette models %v missing a sonnet/opus/haiku family", models)
	}

	// The recorded discovery record is itself non-empty.
	if rec := reader.Discovery(); rec == nil || len(rec.Models) == 0 {
		t.Fatal("cassette discovery record is empty")
	}
}

